class A:
 @property
 def x(self):
  print('get')
  return 4
 @x.setter
 def x(self,value): self.saved=value
 @x.deleter
 def x(self): print('delete')
a=A()
setattr(a,'x',8)
print(getattr(a,'x'),a.saved)
delattr(a,'x')

class A:
 @property
 def x(self): raise AttributeError('missing')
a=A()
print(getattr(a,'x',8),hasattr(a,'x'))

class A:
 @property
 def x(self): raise ValueError('bad')
print(hasattr(A(),'x'))

class A:
 def __add__(self,other):
  print('left')
  return NotImplemented
class B:
 def __radd__(self,other):
  print('right')
  return [7]
print((A()+B())[0])

class A:
 def __add__(self,other):
  print('left')
  return 1
 def __radd__(self,other):
  print('base-right')
  return 2
class B(A):
 def __radd__(self,other):
  print('sub-right')
  return 3
print(A()+B())

class A:
 def __add__(self,other): return NotImplemented
 def __radd__(self,other):
  print('bad')
  return 1
A()+A()

class A:
 def __add__(self,other): raise AttributeError('body')
A()+1

class A:
 def __new__(cls): return object.__new__(cls)
print(type(A()) is A)
